package smartcampus;
import java.awt.*;import java.sql.*;
public class Session extends Panel{
 TextField plate=UI.field(""),slot=UI.field(""),sessionId=UI.field("");TextArea out=new TextArea();
 Session(Frame f){setLayout(new BorderLayout(10,10));setBackground(UI.BG);add(UI.label("VEHICLE ENTRY / EXIT + AUTOMATIC FEE",22,UI.NAVY),BorderLayout.NORTH);Panel p=new Panel(new GridLayout(0,2,8,8));p.add(new Label("Entry Plate"));p.add(plate);p.add(new Label("Slot Code"));p.add(slot);Button in=UI.button("VEHICLE ENTRY",UI.GREEN);p.add(in);p.add(new Label(""));p.add(new Label("Session ID for Exit"));p.add(sessionId);Button ex=UI.button("VEHICLE EXIT / CALCULATE FEE",UI.ORANGE);p.add(ex);add(p,BorderLayout.WEST);out.setEditable(false);add(out,BorderLayout.CENTER);in.addActionListener(e->entry());ex.addActionListener(e->exit());}
 void entry(){try(Connection c=DB.get()){PreparedStatement p=c.prepareStatement("select vehicle_id from vehicles where plate_number=?");p.setString(1,plate.getText());ResultSet r=p.executeQuery();if(!r.next()){out.setText("Vehicle not found");return;}int vid=r.getInt(1);p=c.prepareStatement("select slot_id from parking_slots where slot_code=? and status in ('Available','Reserved')");p.setString(1,slot.getText());r=p.executeQuery();if(!r.next()){out.setText("Slot unavailable");return;}int sid=r.getInt(1);p=c.prepareStatement("insert into parking_sessions(vehicle_id,slot_id,entry_time,status) values(?,?,now(),'Active')",Statement.RETURN_GENERATED_KEYS);p.setInt(1,vid);p.setInt(2,sid);p.executeUpdate();ResultSet k=p.getGeneratedKeys();k.next();int id=k.getInt(1);c.createStatement().executeUpdate("update parking_slots set status='Occupied' where slot_id="+sid);out.setText("ENTRY SUCCESS. Session ID = "+id);sessionId.setText(""+id);}catch(Exception e){out.setText("Error: "+e.getMessage());}}
 void exit(){try(Connection c=DB.get()){int id=Integer.parseInt(sessionId.getText());CallableStatement p=c.prepareCall("{call calculate_parking_fee(?,?)}");p.setInt(1,id);p.registerOutParameter(2,Types.DECIMAL);p.execute();double fee=p.getDouble(2);out.setText("EXIT COMPLETE\nSession: "+id+"\nParking Fee: Rs. "+String.format("%.2f",fee)+"\nPayment record created.");}catch(Exception e){out.setText("Exit error: "+e.getMessage());}}
}
